    "topic": "Ứng dụng AI thực chiến",
    "tags": [
      "AI Marketing",
      "Chăm sóc khách hàng"
    ],
    "featuredImage": "https://marketing2student.com/wp-content/uploads/ai-goi-y-cho-nhan-vien-ho-tro-cover-69f16df4ad2c.webp",
    "publishedAt": "2026-11-22",
    "modifiedAt": "2026-11-26",
