    "tags": [
      "IMC"
    ],
    "featuredImage": "https://marketing2student.com/wp-content/uploads/Slack-Lam-bung-no-linh-vuc-giao-tiep-trong-kinh-doanh.jpg",
    "publishedAt": "2025-05-03",
    "modifiedAt": "2025-05-03",
    "readTime": "15 phút đọc",
